  }
  let sTR = trs.slice(0, period).reduce((s,x)=>s+x,0);
  let sPDM = plusDM.slice(0, period).reduce((s,x)=>s+x,0);
  let sMDM = minusDM.slice(0, period).reduce((s,x)=>s+x,0);
  const dx = [];
  for (let i = period; i < trs.length; i++) {
    sTR = sTR - sTR/period + trs[i];
